if (!items || items.length === 0) return [{json: {}}];
const inputData = items[0].json;
const body = inputData.body || {};
const runId = body.run_id;
const docId = body.document_id;

const now = new Date().toISOString();

return [
  {
    json: {
      run_id: runId,
      document_id: docId,
      started_at: now,
      update_url: 'https://hvlsuwdqtffiilvampxq.supabase.co/rest/v1/contract_runs?run_id=eq.' + runId,
      processing_payload: {
        status: "PROCESSING",
        started_at: now
      },
      extraction_payload: {
        document_id: docId
      },
      completed_payload: {
        status: "COMPLETED",
        completed_at: now
      }
    }
  }
];

const text = $json.extracted_text || $json.text || '';
const prevJson = $('Pre-calc Params').first().json;

const aiPayload = {
  model: 'gpt-4o',
  temperature: 0,
  messages: [
    {
      role: 'system',
      content: 'Extract all contract clauses from this document. Return JSON array with objects containing: clause_id (sequential string like clause_1), clause_text (full text), heading (if any).'
    },
    {
      role: 'user',
      content: text
    }
  ],
  response_format: { type: 'json_object' }
};

return [{
  json: {
    ...prevJson,
    ai_payload: aiPayload,
    extracted_text: text
  }
}];

const prevJson = $('Pre-calc Params').first().json;
const aiResponse = $json;

// UUID generator compatible with n8n Cloud
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

// UUID validator (PO-mandated hardening)
const isUuid = (s) => typeof s === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(s);

// Validate required UUIDs before proceeding
if (!isUuid(prevJson.document_id)) {
  throw new Error(`Invalid document_id UUID: ${prevJson.document_id}`);
}
if (!isUuid(prevJson.run_id)) {
  throw new Error(`Invalid run_id UUID: ${prevJson.run_id}`);
}

let clauses = [];
try {
  const content = aiResponse.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);
  clauses = parsed.clauses || parsed.items || (Array.isArray(parsed) ? parsed : []);
} catch (e) {
  console.log('Parse error:', e.message);
}

if (clauses.length === 0) {
  throw new Error('AI Parse returned 0 clauses - cannot proceed with empty extraction');
}

return clauses.map((c, i) => ({
  json: {
    ...prevJson,
    clause_instance_id: uuid(),
    clause_id: c.clause_id || `clause_${i+1}`,
    clause_text: c.clause_text || c.text || '',
    heading: c.heading || '',
    total_clauses: clauses.length,
    clause_index: i
  }
}));

// Collect pipeline metrics
const data = $json;
const precalc = $('Pre-calc Params').first().json;
const results = data.results || [];

// Calculate timing
const startTime = new Date(precalc.started_at);
const endTime = new Date();
const totalDurationMs = endTime - startTime;

// Aggregate clause stats
let clausesAutoPassed = 0;
let clausesEscalated = 0;
let clausesBlocked = 0;
let totalRagScore = 0;
let ragCount = 0;

for (const r of results) {
  const decision = r._internal?.decision || r.decision || '';
  if (decision === 'AUTO_PASS') clausesAutoPassed++;
  else if (decision === 'ESCALATE_HUMAN' || r.needs_review) clausesEscalated++;
  else if (decision === 'BLOCK_EXPORT') clausesBlocked++;
  if (r._internal?.avg_rag_score) {
    totalRagScore += r._internal.avg_rag_score;
    ragCount++;
  }
}

return [{
  json: {
    ...data,
    run_id: precalc.run_id,
    document_id: precalc.document_id,
    _pipeline_metrics: {
      run_id: precalc.run_id,
      total_duration_ms: totalDurationMs,
      total_clauses: results.length,
      clauses_auto_passed: clausesAutoPassed,
      clauses_escalated: clausesEscalated,
      clauses_blocked: clausesBlocked,
      avg_rag_score: ragCount > 0 ? totalRagScore / ragCount : null,
      workflow_version: 'v3.1-stability'
    }
  }
}];

// PO-mandated: Verify insert succeeded before calling W2
const insertResult = $json;

// Check if we have data (Insert Clauses returns the inserted row with Prefer: return=representation)
const data = Array.isArray(insertResult) ? insertResult[0] : insertResult;
if (!data || !data.id) {
  throw new Error('Insert Clauses failed - no ID returned. Check Supabase logs for constraint violations.');
}

// Log success for observability
console.log(`✓ Clause inserted: ${data.id}`);

return [{ json: data }];
